q=W/'actual-own-whole-two-case-tax-comparison-without-interestgroup-analysis-counterexample.json';assert not q.exists();q.write_text(json.dumps({'goalId':'51bcbc9e-7a1c-5caa-9766-9ab97fa72f04','scope':'Two own complete answers demonstrate non-universality of interest-group hardgate; no learner, released assessment or human result claimed.','ownWholeAnswers':[{'case':'income-and-consumption-model','answerDe':'Die direkte Einkommensteuer ergibt0,1×20000=2000 und0,1×60000=6000, beide10Prozent Einkommen. Die20Prozent Steuer auf gegebenen Nettoverbrauch10000 ergibt bei beiden2000; das sind10Prozent beziehungsweise3,33Prozent Einkommen. Die verschiedenen Basen erklären den Unterschied trotz einheitlicher Sätze. Die vorgegebene Vollüberwälzung macht in diesem Fall Käufer wirtschaftlich belastet; andere Konsumanteile oder Überwälzung könnten das Urteil ändern, daher keine allgemeine Armuts-/Gerechtigkeitsgarantie.'},{'case':'legal-debtor-and-incidence','answerDe':'Gewinnsteuer erfasst Gewinn direkt, Stücksteuer den erfassten Konsum indirekt; beide können vom Unternehmen abgeführt werden. Nur bei der Stücksteuer ist eine Hälfteüberwälzung gegeben, also Käufer-/Verkäuferteilung der Last. Ohne Lohn-, Preis-, Absatz- und Verhaltensdaten kann ich die endgültige Gewinnsteuerinzidenz nicht sicher bestimmen. Direkt bedeutet weder unveränderte Entscheidungen noch unmögliche Weitergabe. Rechtliche Zahlungspflicht und wirtschaftliches Tragen sind verschiedene Fragen.'}],'actualMissingPrerequisitePerformance':'No state/municipal interest, association/party position, Bundesrat channel or group-power analysis appears anywhere, while both whole tax-comparison performances are shown.','minimalFixLane':'Requires only; descriptions remain suitable. Existing effect basis or orientation successor requires separate independent qualification, not self-approved.','blind':True,'humanClaims':False},ensure_ascii=False,indent=2)+'\n')
urls=[('https://www.bundesgesundheitsministerium.de/presse/pressemitteilungen/finanzkommission-gesundheit-ergebnisse-30-03-26','Actual30March2026 commission recommendations, not enacted reform; conditional15billion2027/40billion2030 gap. Original source date kept separate from current page navigation.'),('https://www.bundesregierung.de/breg-de/service/newsletter-und-abos/newsletter-verbraucherschutz/rentenbericht-2025-2394260','Actual19November2025 account: model18.6through2027/21.2in2039; assumptions and expressly not forecasts. No current enacted future rates claimed.'),('https://www.gesetze-im-internet.de/gg/art_109.html','Actual ownGET/ISO8859-1 reading: general borrowing principle, cyclical/emergency mechanism, federal0.35percent, qualified security-above1percent deduction and aggregate Länder0.35percent. No investment-only exception.'),('https://www.gesetze-im-internet.de/gg/art_115.html','Actual ownGET/ISO8859-1 reading: authorisation, structural/cyclical rules, specific deductions, control account and emergency majority plus repayment plan are distinct.'),('https://www.consilium.europa.eu/en/policies/economic-governance-framework/','Actual rules sections read: treaty3/60references, multiannual net-expenditure path, Council/Commission roles, control account, activation/duration and Germany10October2025clause. No all-states sanction automatism or unactivated-exception inference.'),('https://www.gesetze-im-internet.de/gg/art_105.html','Actual ownGET/ISO8859-1 reading of paragraph3: federal tax laws involving Länder/municipal revenue need Bundesrat consent; not municipal federal legislative power.')]
